1→import { NextRequest, NextResponse } from "next/server";
2→import { listClients, type ClientRecord } from "@/lib/clientRegistry";
3→
4→/**
5→ * Client management API.
6→ *
7→ * GET /api/clients            -> every customer (order-first, unlinked sites too)
8→ * GET /api/clients?q=acme     -> free-text search over name/email/site/package/key
9→ * GET /api/clients?status=... -> focused work queues (groups below)
10→ *
11→ * A "client" aggregates an order + license + live site, so this single endpoint
12→ * powers the whole /licenses console.
13→ */
14→
15→const GROUPS: Record<string, (c: ClientRecord) => boolean> = {
16→  all: () => true,
17→  active: (c) => c.license.effective === "active",
18→  expiring: (c) => c.license.expiringSoon,
19→  expired: (c) => c.license.effective === "expired",
20→  unpaid: (c) => c.paymentStatus === "pending_payment" || c.paymentStatus === "pending_review",
21→  failed: (c) => c.paymentStatus === "failed",
22→  completed: (c) => c.paymentStatus === "completed",
23→  readonly: (c) => c.remoteAccess === "readonly",
24→  unlinked: (c) => c.license.effective === "none" || c.paymentStatus === "unlinked",
25→};
26→
27→export async function GET(req: NextRequest) {
28→  try {
29→    const { searchParams } = new URL(req.url);
30→    const q = searchParams.get("q") || undefined;
31→    const status = (searchParams.get("status") || "all").toLowerCase();
32→
33→    const { clients, totals } = await listClients(q);
34→    const predicate = GROUPS[status] || GROUPS.all;
35→    const filtered = clients.filter(predicate);
36→
37→    return NextResponse.json({
38→      success: true,
39→      count: filtered.length,
40→      totals,
41→      groups: Object.keys(GROUPS),
42→      clients: filtered,
43→    });
44→  } catch (err: any) {
45→    return NextResponse.json({ success: false, error: err?.message || "Could not load clients." }, { status: 500 });
46→  }
47→}
EOF

