202→  supportedActions: string[];
203→  coreVersion: string | null;
204→  accessMode: ClientAccessMode;
205→  restrictionRules: Array<{ match: string; mode: string }>;
206→  plugins: Array<{ slug: string; name: string; version: string | null; status: string; active: boolean }>;
