213→/**
214→ * Live "what is actually on the server" probe.
215→ *
216→ * Prefers the v3.2.0 `site_overview` action (core version + plugin list +
217→ * access mode). When the client still runs an older auth.php the call is
218→ * rejected with "Unknown action"; we then fall back to `diagnostics` and flag
219→ * the answer as partial so the UI can tell the operator to re-upload the agent
220→ * instead of silently showing nothing.
221→ */
222→export async function readSiteOverview(site: Site): Promise<SiteOverview> {
223→  const agentUrl = getAuthPhpUrl(site.domain, site.path) || getAgentUrl(site.domain, site.path);
224→  const base: SiteOverview = {
225→    ok: false, partial: false, message: "", agentUrl,
226→    agentVersion: null, supportedActions: [], coreVersion: null, accessMode: "unknown",
227→    restrictionRules: [], plugins: [], license: null, phpVersion: null, serverSoftware: null,
228→  };
229→
230→  const overview = await agentCall(site, "site_overview");
231→  if (overview.ok) {
232→    const d = overview.data || {};
233→    return {
234→      ...base,
235→      ok: true,
236→      message: d.message || "Live server overview received.",
237→      agentVersion: d.agent_version || null,
238→      supportedActions: Array.isArray(d.supported_actions) ? d.supported_actions : [],
239→      coreVersion: d.core_version || null,
240→      accessMode: d.access_mode === "readonly" || d.access_mode === "full" ? d.access_mode : "unknown",
241→      restrictionRules: Array.isArray(d.restriction_rules) ? d.restriction_rules : [],
242→      plugins: Array.isArray(d.plugins) ? d.plugins : [],
243→      license: d.license || null,
244→      phpVersion: d.php_version || null,
245→      serverSoftware: d.server_software || null,
246→      raw: d,
247→    };
248→  }
249→
250→  const diag = await agentCall(site, "diagnostics");
251→  if (!diag.ok) {
252→    return { ...base, message: overview.error || diag.error || "Agent unreachable." };
253→  }
254→  const d = diag.data || {};
255→  const stale = /unknown action/i.test(String(overview.error || ""));
256→  return {
257→    ...base,
258→    partial: true,
259→    message: stale
260→      ? "This site runs an older agent (no site_overview). Core version + plugin list need a fresh auth.php upload."
261→      : `Overview unavailable (${overview.error || "agent error"}); showing diagnostics only.`,
262→    agentVersion: d.agent_version || null,
263→    supportedActions: Array.isArray(d.supported_actions) ? d.supported_actions : [],
264→    phpVersion: d.capabilities?.php_version || null,
265→    serverSoftware: d.server_software || null,
266→    raw: d,
267→  };
268→}
