271→  checkedAt: string;
272→  http: { ok: boolean; statusCode: number | null; latencyMs: number | null; error: string | null };
273→  agent: { reachable: boolean; message: string; version: string | null; capabilities: any };
274→  installer: {
275→    reachable: boolean; message: string; installed: boolean | null; db_ok: boolean | null;
276→    migrationsApplied: number | null; licenseKeySet: boolean | null;
277→  };
278→  overview: SiteOverview;
279→};
