281→/** Live site health: public HTTP + agent diagnostics + headless installer status. */
282→export async function readClientHealth(site: Site): Promise<ClientHealth> {
283→  const siteUrl = site.domain.startsWith("http") ? site.domain : `https://${site.domain}`;
284→  const started = Date.now();
285→  let ok = false;
286→  let statusCode: number | null = null;
287→  let error: string | null = null;
288→  let latencyMs: number | null = null;
289→  try {
290→    const res = await fetch(siteUrl, { method: "HEAD", redirect: "follow", signal: AbortSignal.timeout(3_500) });
291→    statusCode = res.status;
292→    ok = res.status >= 200 && res.status < 500;
293→    latencyMs = Date.now() - started;
294→    if (!ok) error = `HTTP ${res.status}`;
295→  } catch (err: any) {
296→    error = err?.message || "request failed";
297→    latencyMs = Date.now() - started;
298→  }
299→
300→  const diag = await agentCall(site, "diagnostics", {}, 12_000);
301→  const inst = await getAppInstallStatus(siteTarget(site), site.handshakeToken);
302→  const overview = await readSiteOverview(site);
303→
304→  const health: ClientHealth = {
305→    checkedAt: new Date().toISOString(),
306→    http: { ok, statusCode, latencyMs, error },
307→    agent: {
308→      reachable: diag.ok,
309→      message: diag.ok
310→        ? `Agent online (${diag.data?.status || "READY"}) | ${diag.data?.capabilities?.php_version || "PHP ?"}`
311→        : diag.error,
312→      version: diag.data?.agent_version || null,
313→      capabilities: diag.data?.capabilities || null,
314→    },
315→    installer: {
316→      reachable: inst.ok,
317→      message: inst.message,
318→      installed: inst.ok ? Boolean(inst.data?.installed) : null,
319→      db_ok: inst.ok ? Boolean(inst.data?.db_ok) : null,
320→      migrationsApplied: inst.ok ? Number(inst.data?.migrations?.applied ?? 0) : null,
321→      licenseKeySet: inst.ok ? Boolean(inst.data?.license_key_set) : null,
322→    },
323→    overview,
324→  };
325→
326→  await updateSite(site.id, {
327→    status: ok ? "ONLINE" : "OFFLINE",
328→    latency: latencyMs != null ? `${latencyMs}ms` : site.latency,
329→    lastHealthAt: health.checkedAt,
330→    lastHealthStatus: ok ? "ONLINE" : "OFFLINE",
331→    agentVersion: overview.agentVersion || health.agent.version || site.agentVersion,
332→    coreVersion: overview.coreVersion || site.coreVersion,
333→    activePlugins: overview.plugins.length ? overview.plugins.filter((p) => p.active).map((p) => p.slug) : site.activePlugins,
334→    remoteAccess: overview.accessMode !== "unknown" ? overview.accessMode : site.remoteAccess,
335→  }).catch(() => null);
336→
337→  return health;
338→}
