455→/** Every customer Master knows about — orders first, then sites nobody ordered. */
456→export async function listClients(query?: string): Promise<ClientListResult> {
457→  const [orders, licenses, sites] = await Promise.all([getOrders(), getLicenses(), getSites()]);
458→  const pkgIds = new Set<string>();
459→  orders.forEach((o) => o.package_id && pkgIds.add(o.package_id));
460→  sites.forEach((s) => s.package_id && pkgIds.add(s.package_id));
461→  const pkgMap = new Map<string, Package | null>();
462→  await Promise.all(Array.from(pkgIds).map(async (id) => { pkgMap.set(id, (await getPackage(id)) || null); }));
463→
464→  const claimedSiteIds = new Set<string>();
465→  const clients: ClientRecord[] = [];
466→
467→  for (const order of orders) {
468→    const { license, site } = resolveLinks(order, licenses, sites);
469→    if (site) claimedSiteIds.add(site.id);
470→    clients.push(clientFromParts(order, license, site, pkgMap.get(order.package_id) || null));
471→  }
472→  for (const site of sites) {
473→    if (claimedSiteIds.has(site.id)) continue;
474→    const license = licenses.find((l) => l.siteId === site.id) || null;
475→    clients.push(clientFromSite(site, license, site.package_id ? pkgMap.get(site.package_id) || null : null));
476→  }
477→
478→  clients.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
479→
480→  const q = String(query || "").trim().toLowerCase();
481→  const filtered = q
482→    ? clients.filter((c) =>
483→        [c.id, c.orderId, c.contactName, c.contactEmail, c.siteUrl, c.packageName, c.packageSlug, c.license.keyLast4, c.siteId]
484→          .filter(Boolean)
485→          .some((v) => String(v).toLowerCase().includes(q))
486→      )
487→    : clients;
488→
489→  return {
490→    clients: filtered,
491→    totals: {
492→      clients: clients.length,
493→      active: clients.filter((c) => c.license.effective === "active").length,
494→      expiringSoon: clients.filter((c) => c.license.expiringSoon).length,
495→      expired: clients.filter((c) => c.license.effective === "expired").length,
496→      awaitingPayment: clients.filter((c) => c.paymentStatus === "pending_review" || c.paymentStatus === "pending_payment").length,
497→      failedSetup: clients.filter((c) => c.paymentStatus === "failed").length,
498→    },
499→  };
500→}
