511→/** Full client record for the detail drawer: every stored field + optional live probe. */
512→export async function getClientDetail(id: string, opts: { live?: boolean } = {}): Promise<ClientDetail | null> {
513→  const [licenses, sites, order] = await Promise.all([getLicenses(), getSites(), getOrder(id)]);
514→
515→  let license: LicenseRecord | null = null;
516→  let site: Site | null = null;
517→  let resolvedOrder: Order | null = order || null;
518→
519→  if (order) {
520→    const links = resolveLinks(order, licenses, sites);
521→    license = links.license;
522→    site = links.site;
523→  } else {
524→    site = sites.find((s) => s.id === id) || null;
525→    license = site
526→      ? licenses.find((l) => l.siteId === site!.id) || licenses.find((l) => l.id === site!.licenseId) || null
527→      : licenses.find((l) => l.id === id) || null;
528→    if (!site && license?.siteId) site = sites.find((s) => s.id === license.siteId) || null;
529→    if (!resolvedOrder && license?.orderId) resolvedOrder = (await getOrder(license.orderId)) || null;
530→    if (!site && !resolvedOrder && !license) return null;
531→  }
532→
533→  const packageId = resolvedOrder?.package_id || site?.package_id || license?.package_id || "";
534→  const pkg = packageId ? (await getPackage(packageId)) || null : null;
535→
536→  let health: ClientHealth | null = null;
537→  if (opts.live && site) health = await readClientHealth(site);
538→  const freshSite: Site | null = site && health ? ((await getSite(site.id)) || site) : site;
539→
540→  const client: ClientRecord =
541→    resolvedOrder
542→      ? clientFromParts(resolvedOrder, license, freshSite, pkg)
543→      : clientFromSite(freshSite as Site, license, pkg);
544→
545→  return {
546→    client,
547→    order: resolvedOrder
548→      ? { ...resolvedOrder, cpanelApiTokenEncrypted: resolvedOrder.cpanelApiTokenEncrypted ? "***" : "" }
549→      : null,
550→    license: license ? { ...license, key_hash: `${license.key_hash.slice(0, 8)}...` } : null,
551→    site: freshSite ? { ...freshSite, handshakeToken: "***", webhookSecret: "***" } : null,
552→    package: pkg,
553→    health,
554→  };
