561→/**
562→ * Push config to the client's live app through the agent's write_config action.
563→ * Used for the remote access mode (SLATE_ACCESS_MODE), restriction rules and the
564→ * LICENSE_KEY after a rotation. Never throws: the caller shows the message.
565→ */
566→export async function writeClientConfig(params: {
567→  site: Site;
568→  order: Order | null;
569→  extraEnv?: Record<string, string>;
570→  restrictions?: Array<{ match: string; mode: string }>;
571→  fixPermissions?: boolean;
572→}) {
573→  const { site, order, extraEnv, restrictions } = params;
574→  const dbPassword = order?.dbPassEncrypted ? decryptSecret(order.dbPassEncrypted) : "";
575→  return targetWriteConfig({
576→    target: siteTarget(site),
577→    credentials: {
578→      db_name: order?.dbName || "",
579→      db_user: order?.dbUser || "",
580→      db_password: dbPassword,
581→      db_host: order?.dbHost || "localhost",
582→    },
583→    newSiteUrl: site.domain,
584→    handshakeToken: site.handshakeToken,
585→    fixPermissions: params.fixPermissions ?? false,
586→    extraEnv,
587→    restrictions,
588→  });
589→}
