591→/**
592→ * Remote access mode.
593→ *  - full     → the package's normal rules are restored (they only bite after expiry)
594→ *  - readonly → every request is read-only on the client ("*" rule + SLATE_ACCESS_MODE)
595→ * The mode is stored on the site so the console shows what was last pushed.
596→ */
597→export async function setRemoteAccess(params: {
598→  site: Site;
599→  order: Order | null;
600→  pkg: Package | null;
601→  mode: "full" | "readonly";
602→}) {
603→  const { site, order, pkg, mode } = params;
604→  const restrictions = mode === "readonly"
605→    ? [{ match: "*", mode: "readonly" }]
606→    : (pkg?.restrictions || []);
607→
608→  const res = await writeClientConfig({
609→    site,
610→    order,
611→    extraEnv: { SLATE_ACCESS_MODE: mode },
612→    restrictions,
613→  });
614→
615→  if (res.ok) {
616→    await updateSite(site.id, {
617→      remoteAccess: mode,
618→      remoteAccessUpdatedAt: new Date().toISOString(),
619→    }).catch(() => null);
620→    await addDeployment({
621→      siteId: site.id,
622→      domain: site.domain,
623→      repo: order?.package_id || "remote-access",
624→      commitSha: `access-${mode}`,
625→      actor: "master-ops",
626→      status: "SUCCESS",
627→      duration: "0.0s",
628→      logs: [`[${new Date().toLocaleTimeString()}] Remote access mode pushed: ${mode}`, res.message],
629→    }).catch(() => null);
630→  }
631→
632→  return { ok: res.ok, mode, message: res.message, restrictions };
633→}
