635→/** New key for the SAME license row (no new entitlement) + push it to the client. */
636→export async function rotateLicenseKey(params: {
637→  order: Order;
638→  license: LicenseRecord;
639→  site: Site | null;
640→  pkg: Package | null;
641→  notify?: boolean;
642→}) {
643→  const { order, license, site, pkg } = params;
644→  const rawKey = generateLicenseKey();
645→  const expiresAt = calcRenewedExpiry(license.expires_at, license.billing_cycle);
646→
647→  const updated = await updateLicense(license.id, {
648→    key_hash: hashLicenseKey(rawKey),
649→    key_last4: rawKey.slice(-4),
650→    key_signature: signLicensePayload(license.domain, pkg?.slug || license.package_slug, expiresAt),
651→    status: "active",
652→    starts_at: new Date().toISOString(),
653→    expires_at: expiresAt,
654→    activation_count: 0,
655→  });
656→  await updateOrder(order.id, { licenseKeyLast4: rawKey.slice(-4) }).catch(() => null);
657→
658→  let pushed = false;
659→  let pushMessage = "No site linked yet — the client activates the new key from the activation page.";
660→  if (site) {
661→    const res = await writeClientConfig({ site, order, extraEnv: { LICENSE_KEY: rawKey } });
662→    pushed = res.ok;
663→    pushMessage = res.message;
664→  }
665→
666→  const warnings: string[] = [];
667→  if (params.notify !== false) {
668→    const mail = await sendMail(licenseIssuedMail(order.contactEmail, rawKey, license.domain, pkg?.name || license.package_slug, expiresAt));
669→    if (!mail.ok) warnings.push(`Email not sent (${mail.message}). Copy the key from this screen.`);
670→  }
671→
672→  return {
673→    ok: true,
674→    key: rawKey,
675→    masked: maskLicenseKey(`${rawKey.slice(-4)}`),
676→    expiresAt,
677→    license: updated,
678→    pushed,
679→    pushMessage,
680→    warnings,
681→  };
682→}
